// sizeof(values)는 세 원소 전체 크기입니다.
// sizeof(first)는 포인터 타입의 크기입니다.

#include <array>
#include <span>

int Sum(std::span<const int> values) {
    int result{};
    for (int value : values) result += value;
    return result;
}
// std::array<int, 3> a{10, 20, 30};를 Sum(a)로 전달할 수 있습니다.
// 합계가 int 범위 안에 드는 작은 값이라는 전제가 있습니다.

