#include "check.hpp"
#include <algorithm>
#include <array>
#include <cstddef>
#include <cstring>
#include <random>
#include <span>
#include <stdexcept>
#include <string>
#include <string_view>
#include <variant>
#include <vector>

// span은 원소를 소유하지 않는 연속 구간이다. 호출 중 원본의 수명과 주소가 유효해야 한다.
// 이 합계 예제는 int로 표현 가능한 작은 값만 사용한다.
int Sum(std::span<const int> values) {
    int result{};
    for (int value : values) result += value;
    return result;
}

// name은 문자열을 직접 소유한다. sizeof(Item)을 파일 포맷의 크기로 사용하면 안 된다.
struct Item {
    int id;
    std::string name;
    int quantity;
};

int main() {
    // array는 고정 개수의 원소를 소유하고 span으로 그 구간을 빌려 줄 수 있다.
    std::array<int, 3> a{10, 20, 30};
    CHECK(Sum(a) == 60);

    std::vector<int> v;
    v.reserve(4);
    // reserve는 저장 공간만 확보한다. 아직 접근 가능한 원소는 하나도 없다.
    CHECK(v.empty());
    CHECK(v.capacity() >= 4);

    // resize가 세 원소를 만들며, 이 int 원소들의 초기값은 0이다.
    v.resize(3);
    CHECK(v.size() == 3);
    CHECK(v[0] == 0);
    v[1] = 8;
    CHECK(Sum(v) == 8);

    // 유효한 인덱스는 0, 1, 2이다. at은 범위 밖 접근을 예외로 알린다.
    bool rejected = false;
    try { (void)v.at(3); }
    catch (const std::out_of_range&) { rejected = true; }
    CHECK(rejected);

    const auto old_capacity = v.capacity();
    // 현재 capacity보다 크게 요청해 재할당을 일으킨다.
    // 이전 원소 포인터·참조·반복자는 보관하거나 검사하지 않는다.
    v.reserve(old_capacity + 1);
    CHECK(v.capacity() > old_capacity);
    CHECK(v[1] == 8);

    // grid는 길이 3인 행 배열 두 개다. row는 int**가 아니라 행 배열 포인터다.
    int grid[2][3]{{1,2,3},{4,5,6}};
    int (*row)[3] = grid;
    CHECK(row[1][2] == 6);
    // 평탄한 vector에서는 행 * 열 개수 + 열로 인덱스를 계산한다.
    std::vector<int> flat{1,2,3,4,5,6};
    CHECK(flat.at(1 * 3 + 2) == 6);

    // string은 길이를 보관하므로 내부 널도 원소다. C 문자열 함수는 첫 널에서 멈춘다.
    std::string embedded{"a\0b", 3};
    CHECK(embedded.size() == 3);
    CHECK(std::strlen(embedded.c_str()) == 1);
    std::string name{"Potion"};
    const std::string_view view{name};
    // view는 name을 소유하지 않는다. 이 예제에서는 name의 수명과 내용을 유지한다.
    CHECK(view == "Potion");
    // strcmp는 음수·0·양수의 의미만 사용한다. 정확히 -1이나 1일 필요는 없다.
    CHECK(std::strcmp("a", "b") < 0);
    CHECK(std::strcmp("b", "b") == 0);

    std::vector<Item> items{{2,"Mana",1},{1,"Health",3},{3,"Shield",1}};
    std::sort(items.begin(), items.end(), [](const Item& x, const Item& y) {
        // 수량 내림차순, 같은 수량에서는 ID 오름차순으로 비교한다.
        return x.quantity != y.quantity ? x.quantity > y.quantity : x.id < y.id;
    });
    CHECK(items[0].id == 1);
    CHECK(items[1].id == 2);
    CHECK(items[2].id == 3);

    // variant는 현재 활성 타입을 추적한다. 활성 타입에 맞춰 읽는다.
    std::variant<int, std::string> data{7};
    CHECK(std::get<int>(data) == 7);
    data = std::string{"text"};
    CHECK(std::holds_alternative<std::string>(data));

    // 같은 엔진과 시드는 같은 엔진 출력을 만든다. 분포 변환과는 구별한다.
    std::mt19937 engine_a{1234u}, engine_b{1234u};
    for (int i = 0; i < 8; ++i) CHECK(engine_a() == engine_b());
    std::uniform_int_distribution<int> die{1, 6};
    // 이 실험은 20번의 결과 범위만 확인한다. 통계적 균등성 검증은 아니다.
    for (int i = 0; i < 20; ++i) {
        int roll = die(engine_a);
        CHECK(roll >= 1 && roll <= 6);
    }
    // 크기와 정렬 요구는 현재 구현의 관찰값이며 모든 플랫폼의 고정값이 아니다.
    std::cout << "sizeof(Item)=" << sizeof(Item) << " alignof(Item)=" << alignof(Item) << '\n';
    Report();
}

#include "check.hpp"
#include <algorithm>
#include <cstddef>
#include <limits>
#include <memory>
#include <stdexcept>

// int만 다루는 학습용 버퍼다. std::vector의 범용 구현이나 대체품이 아니다.
class IntBuffer {
public:
    IntBuffer() = default;
    // 복사·이동 정책을 구현하지 않았으므로 네 연산을 명시적으로 금지한다.
    IntBuffer(const IntBuffer&) = delete;
    IntBuffer& operator=(const IntBuffer&) = delete;
    IntBuffer(IntBuffer&&) = delete;
    IntBuffer& operator=(IntBuffer&&) = delete;

    void PushBack(int value) {
        if (size_ == capacity_) {
            // 원소 개수와 바이트 수의 범위를 생각하며, 두 배 계산 전에 상한을 검사한다.
            constexpr auto limit = std::numeric_limits<std::size_t>::max() / sizeof(int);
            if (capacity_ > limit / 2) throw std::length_error("capacity overflow");
            // 0 → 2 → 4 → 8 ... 은 이 클래스가 선택한 성장 정책이다.
            const auto next_capacity = capacity_ == 0 ? std::size_t{2} : capacity_ * 2;
            auto next = std::make_unique<int[]>(next_capacity);
            if (size_ != 0) std::copy_n(data_.get(), size_, next.get());
            // 새 할당과 int 복사를 마친 뒤 소유권을 옮긴다. 이때 이전 할당이 해제된다.
            // 일반 타입의 생성·복사 예외 처리까지 구현한 범용 컨테이너는 아니다.
            data_ = std::move(next);
            capacity_ = next_capacity;
        }
        data_[size_++] = value;
    }

    int At(std::size_t index) const {
        // 예약 공간이 아니라 현재 논리적 원소 수를 기준으로 접근을 제한한다.
        if (index >= size_) throw std::out_of_range("index");
        return data_[index];
    }

    std::size_t Size() const { return size_; }
    std::size_t Capacity() const { return capacity_; }

private:
    // unique_ptr가 할당을 소유하고 클래스 소멸 시 배열을 자동 해제한다.
    std::unique_ptr<int[]> data_;
    std::size_t size_{};
    std::size_t capacity_{};
};

int main() {
    IntBuffer buffer;
    CHECK(buffer.Size() == 0);
    bool rejected = false;
    try { (void)buffer.At(0); }
    catch(const std::out_of_range&) { rejected = true; }
    CHECK(rejected);

    for (int i = 0; i < 100; ++i) buffer.PushBack(i);
    CHECK(buffer.Size() == 100);
    // 128은 이 구현의 두 배 성장 결과다. std::vector의 capacity를 예측한 값이 아니다.
    CHECK(buffer.Capacity() == 128);
    // 이 한 CHECK 호출 지점이 원소마다 실행되어 런타임에는 100회를 센다.
    for (std::size_t i = 0; i < 100; ++i) CHECK(buffer.At(i) == static_cast<int>(i));
    Report();
}
